*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#314b43;font-synthesis:none}html,body{height:100%;margin:0;overflow:hidden;background:#bdddc7}.game-shell{position:relative;width:100%;height:100%;height:100dvh;overflow:hidden;background:#a4d5b1;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(37,76,51,.18),transparent 20%,transparent 72%,rgba(38,70,53,.13));z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:80px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;color:#fff;text-shadow:0 1px 5px #41664e55}.brand{display:flex;align-items:center;gap:10px;font-family:Nunito,sans-serif;font-size:20px;font-weight:900;letter-spacing:-.7px;color:white;text-decoration:none}.brand-light{font-weight:700;opacity:.8}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:12px;background:#fff2;font-size:22px;border:1px solid #fff4}.location{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;font-size:13px;font-weight:700;letter-spacing:.03em;color:#fff}.location-pin{font-size:20px}.icon-button{width:39px;height:39px;border:1px solid #ffffff62;background:#ffffff20;border-radius:13px;color:white;font-size:20px;cursor:pointer;backdrop-filter:blur(8px);transition:.2s}.icon-button:hover{background:#ffffff40;transform:translateY(-2px)}
.quest-card{position:absolute;z-index:3;top:104px;left:36px;width:272px;padding:19px 20px 16px;border:1px solid #ffffffbd;border-radius:21px;background:rgba(255,253,239,.91);box-shadow:0 12px 40px #365b3d22;backdrop-filter:blur(12px)}.quest-heading{display:flex;align-items:center;gap:7px;color:#81958a;font-size:9px;font-weight:800;letter-spacing:.13em}.quest-icon{font-size:16px;color:#e5ad4e}.quest-live{margin-left:auto;color:#80a88c;font-size:8px;letter-spacing:.1em;display:flex;align-items:center;gap:5px}.quest-live i{width:6px;height:6px;border-radius:50%;background:#79bb83;box-shadow:0 0 0 3px #79bb8325}.quest-card h1{font-family:Nunito,sans-serif;font-size:22px;letter-spacing:-.5px;margin:12px 0 4px;color:#355449}.quest-card p{font-size:11px;line-height:1.55;color:#71857a;margin:0 0 13px}.progress-row{display:flex;align-items:center;gap:10px}.progress-track{height:6px;flex:1;background:#e8eee2;border-radius:8px;overflow:hidden}.progress-track div{height:100%;width:0;background:linear-gradient(90deg,#f1c96e,#e5a84e);border-radius:8px;transition:width .45s cubic-bezier(.2,.8,.2,1)}.progress-row>span{font-size:10px;font-weight:800;color:#71857a}.petal-row{display:flex;gap:7px;padding-top:10px}.petal-row span{width:23px;height:23px;display:grid;place-items:center;border-radius:8px;background:#f0f1e8;color:#d5d9c9;font-size:14px;transition:.3s}.petal-row span.found{background:#fff0c8;color:#e8b44e;box-shadow:0 2px 6px #e2b64b28;transform:rotate(12deg)}.quest-footer{border-top:1px solid #edf0e7;margin-top:12px;padding-top:11px;color:#a1aa94;font-size:10px;font-weight:600}.tiny-spark{color:#e6b75d;font-size:15px;margin-right:4px}
.map-card{position:absolute;z-index:3;right:34px;top:104px;width:208px;padding:13px 14px 11px;background:rgba(255,253,239,.91);border:1px solid #ffffffbd;border-radius:19px;box-shadow:0 12px 40px #365b3d22;backdrop-filter:blur(12px)}.map-title{display:flex;justify-content:space-between;color:#809389;font-size:9px;font-weight:800;letter-spacing:.13em;padding:1px 2px 8px}.map-compass{font-size:8px;letter-spacing:0;color:#a7afa0}.map-card canvas{display:block;width:100%;height:auto;border-radius:10px;background:#d9ebcb}.map-legend{display:flex;align-items:center;gap:5px;padding:8px 2px 0;font-size:9px;color:#98a494}.legend-you{height:7px;width:7px;background:#f27970;border:1px solid white;border-radius:50%;margin-left:5px}.legend-star{font-style:normal;color:#e7ad4d;margin-left:6px;font-size:12px}
.buddy-card{position:absolute;z-index:4;bottom:80px;left:50%;transform:translate(-50%,10px);display:flex;align-items:center;gap:11px;width:min(350px,calc(100% - 34px));padding:12px 15px;border-radius:17px;background:#fffdf1ed;box-shadow:0 8px 35px #2648352a;opacity:0;pointer-events:none;transition:opacity .25s,transform .25s;backdrop-filter:blur(10px)}.buddy-card.show{opacity:1;transform:translate(-50%,0);pointer-events:auto}.buddy-avatar{font-size:27px;width:40px;height:40px;display:grid;place-items:center;background:#e5f1d8;border-radius:13px}.buddy-card>div{display:grid;gap:2px;flex:1}.buddy-card strong{font-family:Nunito,sans-serif;font-size:12px;color:#476354}.buddy-card span:not(.buddy-avatar){font-size:11px;line-height:1.4;color:#809087}.buddy-card button{border:0;background:none;color:#a5b0a1;font-size:21px;cursor:pointer}.interaction{position:absolute;z-index:5;display:none;align-items:center;gap:7px;padding:7px 10px 7px 7px;border-radius:11px;background:#fffdf2e8;box-shadow:0 5px 16px #27493633;color:#607467;font-size:10px;font-weight:700;pointer-events:none;transform:translate(-50%,-100%)}.interaction.visible{display:flex}.keycap{background:#e8f0dd;border-radius:6px;min-width:22px;height:21px;display:grid;place-items:center;color:#648273;font-size:10px;font-weight:800}.toast{position:absolute;z-index:5;top:48%;left:50%;transform:translate(-50%,15px);display:flex;align-items:center;gap:8px;padding:10px 16px;border-radius:30px;background:#fffdf1ed;box-shadow:0 8px 24px #26483522;color:#658172;font-size:12px;font-weight:700;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.toast>span:first-child{color:#e6b44d;font-size:17px}.bottom-hint{position:absolute;z-index:3;bottom:25px;left:50%;transform:translateX(-50%);padding:10px 15px;border-radius:12px;background:#f8f6e8df;color:#718278;font-size:10px;display:flex;align-items:center;gap:5px;white-space:nowrap;box-shadow:0 4px 18px #33593c18}.bottom-hint kbd{font-family:inherit;font-weight:800;font-size:9px;padding:3px 5px;background:#fff;border:1px solid #e8e8d8;border-bottom-width:2px;border-radius:5px;color:#76897b}.bottom-hint span{margin-left:4px}.bottom-hint b{font-weight:400;margin:0 5px;color:#bdc1af}.mobile-hint{display:none}.touch-controls{display:none}
.start-screen,.win-screen{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:rgba(47,76,57,.22);backdrop-filter:blur(4px);transition:opacity .5s,visibility .5s}.start-screen.hidden,.win-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-card,.win-card{position:relative;width:min(410px,calc(100% - 34px));padding:0 38px 29px;text-align:center;border-radius:27px;background:#fffdf3;box-shadow:0 24px 80px #263e3240;overflow:hidden;animation:card-in .6s cubic-bezier(.2,.9,.3,1) both}.start-art{position:relative;height:160px;margin:0 -38px 23px;overflow:hidden;background:linear-gradient(180deg,#c8e7d4,#e2edc9)}.start-art:after{content:'';position:absolute;left:-8%;right:-8%;height:58px;bottom:-29px;border-radius:50%;background:#a7d094}.sun-halo{position:absolute;left:50%;top:23px;width:105px;height:105px;transform:translateX(-50%);border-radius:50%;background:#ffedb9;box-shadow:0 0 0 15px #fff3c633}.art-bunny{position:absolute;z-index:1;left:50%;top:40px;transform:translateX(-50%);font-size:72px;filter:drop-shadow(0 6px 3px #77986728);animation:bob 2.4s ease-in-out infinite}.art-flower{position:absolute;z-index:2;color:#fff4ce;font-size:31px;filter:drop-shadow(0 2px 2px #80986755)}.flower-a{left:22%;bottom:21px}.flower-b{right:22%;bottom:16px;color:#f8b5a2}.art-sparkle{position:absolute;right:29%;top:36px;color:#fff;font-size:19px;animation:twinkle 1.7s ease infinite}.art-butterfly{position:absolute;left:28%;top:45px;color:#fff;font-size:27px;animation:floaty 3s ease-in-out infinite}.eyebrow{display:block;font-size:9px;font-weight:800;letter-spacing:.16em;color:#a2ab8f}.start-card h2,.win-card h2{font-family:Nunito,sans-serif;color:#385549;line-height:1.03;font-weight:900;font-size:34px;letter-spacing:-1.3px;margin:11px 0}.start-card h2 em,.win-card h2 em{font-style:normal;color:#86ad76}.start-card p,.win-card p{color:#829187;font-size:12px;line-height:1.65;margin:10px 0 20px}.play-button{border:0;border-radius:13px;background:#86ad76;color:#fff;font:800 13px 'DM Sans',sans-serif;padding:13px 18px;min-width:178px;cursor:pointer;box-shadow:0 5px 0 #6b935f,0 8px 16px #86ad7630;transition:transform .15s,box-shadow .15s}.play-button span{font-size:17px;margin-left:12px}.play-button:hover{transform:translateY(-2px);box-shadow:0 7px 0 #6b935f,0 10px 20px #86ad7630}.play-button:active{transform:translateY(3px);box-shadow:0 2px 0 #6b935f}.start-note{display:block;margin-top:17px;color:#b1b8a8;font-size:10px}.win-screen{z-index:9;background:#526d4a47}.win-card{padding:42px 38px 33px}.win-star{display:block;font-size:42px;color:#edc05b;text-shadow:0 3px 15px #e9c36366;margin-bottom:9px;animation:twinkle 1.5s infinite}.win-card h2{font-size:31px}.win-card p{margin-bottom:20px}
@keyframes card-in{from{opacity:0;transform:translateY(16px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes bob{0%,100%{transform:translate(-50%,0)}50%{transform:translate(-50%,-6px)}}@keyframes floaty{0%,100%{transform:rotate(-15deg) translateY(0)}50%{transform:rotate(12deg) translateY(-9px)}}@keyframes twinkle{0%,100%{opacity:.55;transform:scale(.85)}50%{opacity:1;transform:scale(1.15)}}
@media(max-width:700px){.topbar{height:62px;padding:0 17px}.brand{font-size:17px}.brand-mark{width:30px;height:30px}.location{top:68px;left:50%;font-size:11px;background:#49694f66;padding:6px 10px;border-radius:20px;white-space:nowrap}.location-pin{font-size:15px}.sound-button{width:34px;height:34px}.quest-card{top:113px;left:13px;width:220px;padding:14px 15px 11px;border-radius:17px}.quest-heading{font-size:8px}.quest-card h1{font-size:19px;margin:8px 0 3px}.quest-card p{font-size:10px;margin-bottom:10px}.petal-row{padding-top:7px;gap:5px}.petal-row span{width:20px;height:20px;font-size:12px}.quest-footer{margin-top:8px;padding-top:8px;font-size:9px}.map-card{top:113px;right:13px;width:124px;padding:9px;border-radius:15px}.map-title{font-size:8px;padding-bottom:6px}.map-legend{font-size:8px;padding-top:5px}.map-card canvas{height:85px;object-fit:cover}.bottom-hint{bottom:calc(18px + env(safe-area-inset-bottom));font-size:9px}.desktop-hint{display:none}.mobile-hint{display:inline}.touch-controls{display:block;position:absolute;z-index:4;bottom:calc(71px + env(safe-area-inset-bottom));left:20px;right:20px;pointer-events:none}.joystick{position:absolute;left:0;bottom:0;width:112px;height:112px;border-radius:50%;background:#fff5;border:1px solid #ffffff9e;box-shadow:0 5px 25px #42614b22;pointer-events:auto;touch-action:none}.joy-knob{position:absolute;left:50%;top:50%;width:46px;height:46px;margin:-23px;border-radius:50%;background:#fffdf0;border:1px solid #fff;box-shadow:0 3px 10px #42614b35;pointer-events:none}.touch-action{position:absolute;right:3px;bottom:18px;width:62px;height:62px;border:1px solid #ffffffb5;background:#fff7;border-radius:50%;color:#53735f;font:800 17px Nunito,sans-serif;box-shadow:0 5px 25px #42614b22;pointer-events:auto;touch-action:manipulation}.buddy-card{bottom:calc(190px + env(safe-area-inset-bottom));width:min(330px,calc(100% - 30px))}.interaction{font-size:9px}.start-card{padding-left:26px;padding-right:26px}.start-art{margin-left:-26px;margin-right:-26px}.vignette{background:linear-gradient(180deg,rgba(37,76,51,.14),transparent 18%,transparent 65%,rgba(38,70,53,.1))}}
@media(max-height:650px) and (min-width:701px){.quest-card{top:82px;padding:14px 16px}.map-card{top:82px}.bottom-hint{bottom:13px}.buddy-card{bottom:57px}}

(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('minimap');
  const mapCtx = mapCanvas.getContext('2d');
  const W = 3200, H = 2300;
  const ui = Object.fromEntries(['start-screen','play-button','win-screen','keep-playing','quest-title','quest-copy','progress-fill','progress-count','petal-row','location-name','buddy-card','buddy-name','buddy-line','buddy-close','interaction','interaction-label','toast','toast-text','sound-toggle','joystick','joy-knob','touch-action'].map(id => [id, document.getElementById(id)]));
  let vw = innerWidth, vh = innerHeight, dpr = 1, started = false, won = false, soundOn = false;
  const rand = (seed) => { let a = seed >>> 0; return () => { a += 0x6D2B79F5; let t = a; t = Math.imul(t ^ t >>> 15, t | 1); t ^= t + Math.imul(t ^ t >>> 7, t | 61); return ((t ^ t >>> 14) >>> 0) / 4294967296; }; };
  const rng = rand(98321);
  const player = {x: 1600, y: 1200, vx: 0, vy: 0, face: 1, step: 0};
  const camera = {x: player.x, y: player.y};
  const keys = new Set();
  const pad = {x:0,y:0,active:false,id:null};
  const stars = [
    {x:900,y:590,found:false,area:'Bluebell Nook'}, {x:2210,y:520,found:false,area:'Sunny Hill'},
    {x:2640,y:1330,found:false,area:'Mushroom Grove'}, {x:1930,y:1900,found:false,area:'Willow Pond'},
    {x:600,y:1630,found:false,area:'Clover Corner'}
  ];
  const friends = [
    {x:1515,y:1130,name:'Pip the frog',emoji:'🐸',line:'A little star is glowing near the bluebells, north-west of here!',color:'#85b89b',wants:true},
    {x:2290,y:1390,name:'Momo the bear',emoji:'🐻',line:'Follow the winding path to the mushroom grove. I saw a sparkle there!',color:'#c68f72',wants:false},
    {x:1250,y:1930,name:'Lulu the lamb',emoji:'🐑',line:'You make this meadow feel like a storybook. Keep going, little friend!',color:'#b8b8ce',wants:false},
    {x:715,y:900,name:'Fern the fox',emoji:'🦊',line:'The stars love quiet places. Try the sunny hill, then the pond.',color:'#dc9b67',wants:false}
  ];
  const trees = [], flowers = [], rocks = [], mushrooms = [], tufts = [];
  for(let i=0;i<230;i++){
    const x=90+rng()*(W-180), y=90+rng()*(H-180);
    // Leave the central glade and main walkways pleasantly open.
    if(Math.hypot(x-1600,y-1200)<210 || Math.hypot(x-900,y-590)<90 || Math.hypot(x-2210,y-520)<95 || Math.hypot(x-2640,y-1330)<100 || Math.hypot(x-1930,y-1900)<95 || Math.hypot(x-600,y-1630)<100) continue;
    if(Math.abs(y-(1200+Math.sin(x/510)*190))<105 || Math.abs(y-(1200-Math.sin(x/520)*260))<95) continue;
    trees.push({x,y,r:24+rng()*23,tint:Math.floor(rng()*4),variant:rng()});
  }
  for(let i=0;i<1500;i++) flowers.push({x:40+rng()*(W-80),y:40+rng()*(H-80),s:2+rng()*2.2,c:Math.floor(rng()*6),p:rng()*6.28});
  for(let i=0;i<85;i++) rocks.push({x:70+rng()*(W-140),y:70+rng()*(H-140),r:8+rng()*13});
  for(let i=0;i<85;i++) mushrooms.push({x:90+rng()*(W-180),y:90+rng()*(H-180),r:5+rng()*5});
  for(let i=0;i<260;i++) tufts.push({x:20+rng()*(W-40),y:20+rng()*(H-40),r:3+rng()*5,a:rng()*6.28});
  const palette=['#fff2cd','#f5a9a0','#fffaf0','#d8b8eb','#f6d47f','#d4eaa7'];
  function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(vw*dpr);canvas.height=Math.round(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
  function worldToScreen(x,y){return {x:x-camera.x+vw/2,y:y-camera.y+vh/2}}
  function visible(x,y,p=80){return x>camera.x-vw/2-p&&x<camera.x+vw/2+p&&y>camera.y-vh/2-p&&y<camera.y+vh/2+p}
  function roundedPath(points,width,color){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=color;ctx.stroke()}
  function pathLine(which){ctx.beginPath();if(which===0){ctx.moveTo(-100,1200);ctx.bezierCurveTo(470,1040,770,1470,1210,1255);ctx.bezierCurveTo(1590,1070,1780,950,2140,1120);ctx.bezierCurveTo(2480,1280,2780,1190,3300,1470)}else{ctx.moveTo(420,2320);ctx.bezierCurveTo(590,1880,900,1750,1180,1470);ctx.bezierCurveTo(1460,1190,1460,760,1750,470);ctx.bezierCurveTo(2100,140,2580,270,3300,190)}ctx.lineWidth=65;ctx.lineCap='round';ctx.strokeStyle='#c1ce9b';ctx.stroke();ctx.lineWidth=54;ctx.strokeStyle='#e7e1b5';ctx.stroke()}
  function drawTerrain(){ctx.fillStyle='#a9d39b';ctx.fillRect(0,0,vw,vh);
    // broad overlapping meadow patches create a soft, painted ground
    const patches=[[350,400,430,'#b4dca2'],[1190,340,500,'#b5dca5'],[2380,350,460,'#afd79b'],[2860,1000,470,'#b8dda8'],[470,1330,490,'#b5dba3'],[1320,2040,470,'#b9dda6'],[2380,1950,510,'#aed49b'],[1740,1000,500,'#a4d292']];
    for(const [x,y,r,c] of patches)if(visible(x,y,r)){let p=worldToScreen(x,y);ctx.beginPath();ctx.ellipse(p.x,p.y,r*1.35,r*.9,-.15,0,Math.PI*2);ctx.fillStyle=c;ctx.fill()}
    // meandering shallow stream in the western meadow
    ctx.save();ctx.translate(-camera.x+vw/2,-camera.y+vh/2);ctx.beginPath();ctx.moveTo(300,0);ctx.bezierCurveTo(520,360,260,650,470,950);ctx.bezierCurveTo(660,1220,390,1450,560,1750);ctx.bezierCurveTo(700,1980,520,2160,710,2400);ctx.lineWidth=100;ctx.lineCap='round';ctx.strokeStyle='#84c9c0';ctx.stroke();ctx.lineWidth=83;ctx.strokeStyle='#9dd8ce';ctx.stroke();ctx.beginPath();ctx.moveTo(300,0);ctx.bezierCurveTo(520,360,260,650,470,950);ctx.bezierCurveTo(660,1220,390,1450,560,1750);ctx.bezierCurveTo(700,1980,520,2160,710,2400);ctx.setLineDash([3,24]);ctx.lineWidth=3;ctx.strokeStyle='#d5f0d7aa';ctx.stroke();ctx.restore();
    pathLine(0);pathLine(1);
    // little flower confetti in the near field
    for(const f of flowers){if(!visible(f.x,f.y,8))continue;const p=worldToScreen(f.x,f.y);ctx.globalAlpha=.55;ctx.fillStyle=palette[f.c];ctx.beginPath();ctx.arc(p.x,p.y,f.s,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
    for(const t of tufts){if(!visible(t.x,t.y,8))continue;const p=worldToScreen(t.x,t.y);ctx.strokeStyle='#6d9d6d66';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.quadraticCurveTo(p.x+Math.cos(t.a)*4,p.y-5,p.x+Math.cos(t.a)*t.r,p.y-Math.sin(t.a)*t.r);ctx.stroke()}
    drawPond();
  }
  function drawPond(){const x=1930,y=1900,p=worldToScreen(x,y);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#8ccdc1';ctx.beginPath();ctx.ellipse(0,0,132,90,-.22,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d4e3a9';ctx.lineWidth=12;ctx.stroke();ctx.fillStyle='#b1e1cf';ctx.beginPath();ctx.ellipse(-8,-5,108,68,-.22,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e6f4d0aa';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(8,-7,77,43,-.22,0,Math.PI*2);ctx.stroke();for(const [lx,ly] of [[-60,-20],[66,28],[20,-47]]){ctx.fillStyle='#77ad78';ctx.beginPath();ctx.ellipse(lx,ly,12,6,.45,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(lx+3,ly-2,3,Math.PI,0);ctx.fill()}ctx.restore()}
  function drawTree(t){if(!visible(t.x,t.y,t.r+35))return;const p=worldToScreen(t.x,t.y),r=t.r;const colors=['#659d69','#71a86b','#5f9767','#7daf70'];ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#416d4d32';ctx.beginPath();ctx.ellipse(5,14,r*.92,r*.47,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#966e4e';ctx.beginPath();ctx.roundRect(-r*.19,-r*.15,r*.38,r*.85,5);ctx.fill();ctx.fillStyle='#a9825b';ctx.beginPath();ctx.roundRect(-r*.09,-r*.12,r*.12,r*.68,4);ctx.fill();ctx.fillStyle=colors[t.tint];ctx.beginPath();ctx.arc(-r*.28,-r*.16,r*.63,0,Math.PI*2);ctx.arc(r*.25,-r*.18,r*.66,0,Math.PI*2);ctx.arc(0,-r*.48,r*.66,0,Math.PI*2);ctx.arc(0,-r*.1,r*.64,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff20';ctx.beginPath();ctx.arc(-r*.27,-r*.47,r*.22,0,Math.PI*2);ctx.fill();ctx.restore()}
