  function drawMushroom(m){if(!visible(m.x,m.y,12))return;const p=worldToScreen(m.x,m.y);ctx.fillStyle='#f0ead4';ctx.fillRect(p.x-2,p.y-1,4,8);ctx.fillStyle='#da8980';ctx.beginPath();ctx.ellipse(p.x,p.y-2,m.r,m.r*.63,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#fff4dc';ctx.beginPath();ctx.arc(p.x-2,p.y-4,1.3,0,6.28);ctx.fill()}
