  function drawStarShape(x,y,r,inner){ctx.beginPath();for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*inner/r:r;let px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py)}ctx.closePath()}
  function drawFriend(f,time){if(!visible(f.x,f.y,45))return;const p=worldToScreen(f.x,f.y),bob=Math.sin(time/450+f.x)*2.5;ctx.save();ctx.translate(p.x,p.y+bob);ctx.fillStyle='#3f67442d';ctx.beginPath();ctx.ellipse(0,12,21,8,0,0,6.28);ctx.fill();ctx.fillStyle='#fff6df';ctx.beginPath();ctx.roundRect(-25,-40,50,59,19);ctx.fill();ctx.strokeStyle='#ffffffaa';ctx.lineWidth=2;ctx.stroke();ctx.font='28px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(f.emoji,0,-12);ctx.fillStyle='#fffdf0';ctx.beginPath();ctx.roundRect(-35,-60,70,20,9);ctx.fill();ctx.fillStyle='#69816e';ctx.font='700 9px DM Sans, sans-serif';ctx.fillText(f.name.split(' ')[0],0,-50);if(Math.hypot(player.x-f.x,player.y-f.y)<105){ctx.fillStyle='#ffe99b';ctx.font='bold 17px sans-serif';ctx.fillText('✦',28,-48)}ctx.restore()}
  function drawHero(time){const p=worldToScreen(player.x,player.y),moving=Math.hypot(player.vx,player.vy)>.3,bob=moving?Math.sin(player.step)*2.5:Math.sin(time/380)*1.5;ctx.save();ctx.translate(p.x,p.y+bob);ctx.fillStyle='#365c403d';ctx.beginPath();ctx.ellipse(0,15,17,7,0,0,Math.PI*2);ctx.fill();ctx.translate(player.face<0?1:0,0);if(player.face<0)ctx.scale(-1,1);
    // ears and little peach inner-ear details
    ctx.fillStyle='#fff7e8';ctx.beginPath();ctx.ellipse(-7,-22,5,14,-.2,0,Math.PI*2);ctx.ellipse(6,-23,5,14,.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f0b5ac';ctx.beginPath();ctx.ellipse(-7,-23,2,8,-.2,0,Math.PI*2);ctx.ellipse(6,-24,2,8,.2,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff9eb';ctx.beginPath();ctx.ellipse(0,-4,16,19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f7c5b7';ctx.beginPath();ctx.arc(-10,1,3.2,0,Math.PI*2);ctx.arc(10,1,3.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#44584c';ctx.beginPath();ctx.arc(-5,-6,1.8,0,Math.PI*2);ctx.arc(5,-6,1.8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d68980';ctx.beginPath();ctx.arc(0,-2,1.8,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a97972';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(-2,3,-4,2);ctx.moveTo(0,0);ctx.quadraticCurveTo(2,3,4,2);ctx.stroke();
