  function drawMinimap(){const w=mapCanvas.width,h=mapCanvas.height,sx=w/W,sy=h/H;mapCtx.clearRect(0,0,w,h);mapCtx.fillStyle='#d5e8c2';mapCtx.fillRect(0,0,w,h);mapCtx.strokeStyle='#9fcebe';mapCtx.lineWidth=6;mapCtx.beginPath();mapCtx.moveTo(17,0);mapCtx.bezierCurveTo(30,34,11,45,33,78);mapCtx.bezierCurveTo(46,102,28,119,42,136);mapCtx.stroke();mapCtx.strokeStyle='#e2dba9';mapCtx.lineWidth=4;mapCtx.beginPath();mapCtx.moveTo(0,72);mapCtx.bezierCurveTo(34,63,46,87,68,74);mapCtx.bezierCurveTo(104,54,112,64,130,73);mapCtx.bezierCurveTo(148,85,162,71,180,90);mapCtx.stroke();mapCtx.fillStyle='#92cbbd';mapCtx.beginPath();mapCtx.ellipse(108,111,10,6,-.2,0,6.28);mapCtx.fill();for(const s of stars)if(!s.found){mapCtx.fillStyle='#e5ae49';mapCtx.beginPath();mapCtx.arc(s.x*sx,s.y*sy,2.4,0,6.28);mapCtx.fill()}mapCtx.fillStyle='#e87872';mapCtx.beginPath();mapCtx.arc(player.x*sx,player.y*sy,4.5,0,6.28);mapCtx.fill();mapCtx.strokeStyle='#fff';mapCtx.lineWidth=1.5;mapCtx.stroke()}
  function movement(){let x=0,y=0;if(keys.has('ArrowLeft')||keys.has('a')||keys.has('A'))x--;if(keys.has('ArrowRight')||keys.has('d')||keys.has('D'))x++;if(keys.has('ArrowUp')||keys.has('w')||keys.has('W'))y--;if(keys.has('ArrowDown')||keys.has('s')||keys.has('S'))y++;x+=pad.x;y+=pad.y;const mag=Math.hypot(x,y);if(mag>1){x/=mag;y/=mag}const speed=3.5;player.vx+=(x*speed-player.vx)*.21;player.vy+=(y*speed-player.vy)*.21;if(Math.abs(player.vx)<.04)player.vx=0;if(Math.abs(player.vy)<.04)player.vy=0;if(player.vx<-.2)player.face=-1;else if(player.vx>.2)player.face=1;const nx=clamp(player.x+player.vx,32,W-32),ny=clamp(player.y+player.vy,30,H-30);if(!isBlocked(nx,player.y))player.x=nx;else player.vx=0;if(!isBlocked(player.x,ny))player.y=ny;else player.vy=0;if(Math.hypot(player.vx,player.vy)>.15)player.step+=.25;camera.x+=(player.x-camera.x)*.1;camera.y+=(player.y-camera.y)*.1;}
