  function updateInteraction(){let near=null,dist=100;for(const f of friends){let d=Math.hypot(player.x-f.x,player.y-f.y);if(d<dist){near=f;dist=d}}if(near&&dist<88){ui.interaction.classList.add('visible');ui.interaction.querySelector('#interaction-label').textContent='Talk';const p=worldToScreen(near.x,near.y-57);ui.interaction.style.left=p.x+'px';ui.interaction.style.top=p.y+'px'}else ui.interaction.classList.remove('visible')}
