  let audio;function playChime(){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(640,audio.currentTime);o.frequency.exponentialRampToValueAtTime(980,audio.currentTime+.18);g.gain.setValueAtTime(.12,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.36);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.37)}catch(e){}}
