  ui['play-button'].addEventListener('click',start);ui['keep-playing'].addEventListener('click',()=>ui['win-screen'].classList.add('hidden'));ui['buddy-close'].addEventListener('click',()=>ui['buddy-card'].classList.remove('show'));ui['touch-action'].addEventListener('pointerdown',e=>{e.preventDefault();interact()});ui['sound-toggle'].addEventListener('click',()=>{soundOn=!soundOn;ui['sound-toggle'].textContent=soundOn?'♫':'♪';ui['sound-toggle'].style.background=soundOn?'#ffffff50':'';if(soundOn)playChime()});
  const joy=ui.joystick,knob=ui['joy-knob'];function setJoy(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=34,d=Math.hypot(dx,dy),scale=d>max?max/d:1;pad.x=dx*scale/max;pad.y=dy*scale/max;knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`}joy.addEventListener('pointerdown',e=>{pad.active=true;pad.id=e.pointerId;joy.setPointerCapture(e.pointerId);setJoy(e)});joy.addEventListener('pointermove',e=>{if(pad.active&&e.pointerId===pad.id)setJoy(e)});function releaseJoy(e){if(pad.active&&e.pointerId===pad.id){pad.active=false;pad.x=pad.y=0;knob.style.transform='translate(0,0)'}}joy.addEventListener('pointerup',releaseJoy);joy.addEventListener('pointercancel',releaseJoy);
  const areas=[['Whispering Meadow',1600,1200],['Bluebell Nook',900,590],['Sunny Hill',2210,520],['Mushroom Grove',2640,1330],['Willow Pond',1930,1900],['Clover Corner',600,1630]];function areaName(){let nearest=areas[0],d0=1e9;for(const a of areas){const d=Math.hypot(player.x-a[1],player.y-a[2]);if(d<d0){nearest=a;d0=d}}return nearest[0]}
  setInterval(()=>{if(started){const a=areaName();document.getElementById('location-name').textContent=a}},550);
  let last=performance.now();function loop(now){let dt=Math.min(34,now-last);last=now;if(started)movement();requestAnimationFrame(loop)}requestAnimationFrame(loop);requestAnimationFrame(draw);
})();

